use anyhow::Result;use synara_process::{ManagedProcess,ProcessSpec};use super::{ProviderAdapter,ProviderMetadata};use async_trait::async_trait;use std::sync::Mutex;
pub struct CliProvider{meta:ProviderMetadata,program:String,process:Mutex<Option<ManagedProcess>>}
impl CliProvider{pub fn new(kind:&str,name:&str,program:&str)->Self{Self{meta:ProviderMetadata{kind:kind.into(),display_name:name.into()},program:program.into(),process:Mutex::new(None)}}}
#[async_trait]impl ProviderAdapter for CliProvider{fn metadata(&self)->ProviderMetadata{self.meta.clone()}async fn start_session(&self,_thread:&str)->Result<String>{let p=tokio::runtime::Handle::current();let spec=ProcessSpec{program:self.program.clone(),args:vec![],cwd:None};let child=p.block_on(ManagedProcess::spawn(spec))?;*self.process.lock().unwrap()=Some(child);Ok(uuid::Uuid::new_v4().to_string())}async fn send_turn(&self,_session:&str,prompt:&str)->Result<()>{let mut guard=self.process.lock().unwrap();if let Some(proc)=guard.as_mut(){use tokio::io::AsyncWriteExt;if let Some(stdin)=proc.child.stdin.as_mut(){stdin.write_all(prompt.as_bytes()).await?;stdin.write_all(b"\n").await?;}}Ok(())}async fn interrupt(&self,_session:&str)->Result<()>{if let Some(mut p)=self.process.lock().unwrap().take(){p.terminate().await?;}Ok(())}}
